window.__posterData({"id": "sheila-daghouti-jaait", "name": "Sheila Daghouti Jaatit", "folder": "Week1_Poster_SheilaDaghoutiJaait_AIVersion.", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// ---------- Constants ----------\nconst CANVAS_W = 600;\nconst CANVAS_H = 800;\nconst DOT_COUNT = 70;\nconst DOT_MIN_SIZE = 6;\nconst DOT_MAX_SIZE = 18;\n\nconst RIPPLE_MAX_RADIUS = 250; // NYTT\nconst RIPPLE_SPEED = 6;        // NYTT\n\nconst COLORS = {\n  green: [57, 255, 20],     // Neongrön\n  yellow: [255, 255, 0],    // Neongul\n  orange: [255, 95, 31],    // Neonorange\n  pink: [255, 20, 147],     // Neonrosa\n  turquoise: [0, 255, 255], // Turkos\n  black: [0, 0, 0],\n  purple: [90, 20, 140],    // Lila bakgrund\n};\n\nconst DOT_COLORS = [\n  COLORS.green,\n  COLORS.yellow,\n  COLORS.orange,\n  COLORS.pink,\n  COLORS.turquoise,\n];\n\nlet bgImg;\nlet ripples = []; // NYTT\n\n// ---------- p5 functions ----------\nasync function setup() {\n  createCanvas(CANVAS_W, CANVAS_H);\n  bgImg = await loadImage(\"img.jpg\");\n}\n\nfunction draw() {\n  if (mouseIsPressed) {\n    // Bakgrunden blir bilden när man trycker\n    background(bgImg);\n    drawDots(DOT_COUNT);\n  } else {\n    // Första bakgrunden som är lila\n    background(COLORS.purple);\n    drawClickHint();\n  }\n\n  drawRipples(); // NYTT (före titeln så att texten hamnar överst)\n\n  drawTitle();\n  drawName();\n}\n\n// NYTT: körs automatiskt av p5 vid varje klick\nfunction mousePressed() {\n  ripples.push({\n    x: mouseX,\n    y: mouseY,\n    radius: 0,\n    color: random(DOT_COLORS),\n  });\n}\n\n// ---------- Helpers ----------\n\n// Ritar små prickar med slumpad position, neonfärg och storlek\nfunction drawDots(count) {\n  noStroke();\n\n  for (let i = 0; i < count; i++) {\n    let x = random(width);\n    let y = random(height);\n    fill(DOT_COLORS[floor(random(DOT_COLORS.length))]);\n    circle(x, y, random(DOT_MIN_SIZE, DOT_MAX_SIZE));\n  }\n}\n\n// NYTT: ritar och uppdaterar alla ringar, och tar bort de som bleknat bort\nfunction drawRipples() {\n  noFill();\n\n  for (let i = ripples.length - 1; i >= 0; i--) {\n    let r = ripples[i];\n    let fade = 1 - r.radius / RIPPLE_MAX_RADIUS; // 1 -> 0\n\n    drawingContext.shadowColor = `rgb(${r.color.join(\", \")})`;\n    drawingContext.shadowBlur = 15;\n\n    stroke(r.color[0], r.color[1], r.color[2], 255 * fade);\n    strokeWeight(2 + 6 * fade);\n    circle(r.x, r.y, r.radius * 2);\n\n    r.radius += RIPPLE_SPEED;\n    if (r.radius >= RIPPLE_MAX_RADIUS) {\n      ripples.splice(i, 1);\n    }\n  }\n\n  // Nollställ glöden så att titeln och namnet inte påverkas\n  drawingContext.shadowBlur = 0;\n}\n\n// Gemensam textfunktion för alla texter\nfunction drawLabel(label, y, size, fillColor, strokeColor, weight) {\n  textAlign(CENTER, CENTER);\n  textFont(\"Impact\");\n  textSize(size);\n  fill(fillColor);\n  stroke(strokeColor);\n  strokeWeight(weight);\n  text(label, width / 2, y);\n}\n\n// Click here!\nfunction drawClickHint() {\n  drawLabel(\"CLICK HERE!\", height / 2 + 90, 34, COLORS.green, COLORS.black, 4);\n}\n\n// NEON RAVE i mitten (pulserande storlek och glöd)\nfunction drawTitle() {\n  let pulse = sin(frameCount * 0.25);\n\n  let size = 97.5 + pulse * 7.5; // 90 - 105 px\n  let glow = 22.5 + pulse * 7.5; // 15 - 30 px\n\n  drawingContext.shadowColor = `rgb(${COLORS.pink.join(\", \")})`;\n  drawingContext.shadowBlur = glow;\n\n  drawLabel(\"NEON RAVE\", CANVAS_H / 2, size, COLORS.yellow, COLORS.pink, 7);\n\n  // Nollställ glöden så att resten av ritningen inte påverkas\n  drawingContext.shadowBlur = 0;\n}\n\n// Mitt namn\nfunction drawName() {\n  drawLabel(\"Sheila Daghouti Jaatit\", 740, 26, COLORS.yellow, COLORS.pink, 4);\n}\n\n// The first time i asked Claude to change the code, didnt affect the lenght of the code much. But i feel like its more structured.\n\n// I liked the change in step 2 (drawTitle) it made the poster seem more alive. \n\n// I feel like the changes in step 3 didint give new energy to the poster. I just noticed that a ring pop up when you press CLICK HERE. Other than that nothing else changed. \n", "assets": {"img.jpg": {"mime": "image/webp", "b64": ""}}});
